```python
import sys

def solve_case(n, K, a):
    # 前缀余数，实际用到下标 2n-1
    prefix = [0] * (2 * n)
    for i in range(1, 2 * n):
        prefix[i] = (prefix[i - 1] + a[(i - 1) % n]) % K

    seen = set()
    right = 0
    ans = 0

    for left in range(1, n + 1):
        limit = left + n - 1
        while right + 1 <= limit and prefix[right + 1] not in seen:
            right += 1
            seen.add(prefix[right])

        ans += right - left + 1

        if left <= right:
            seen.remove(prefix[left])

    return ans

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    T = data[idx]; idx += 1
    out = []
    for _ in range(T):
        n = data[idx]; K = data[idx+1]; idx += 2
        a = data[idx:idx+n]; idx += n
        out.append(str(solve_case(n, K, a)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

